'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var Float64Array = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Float64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'a typed array instance has a `toString` method for serializing a typed array', function test( t ) {
	var arr = new Float64Array( 2 );
	t.strictEqual( hasProp( arr, 'toString' ), true, 'has property' );
	t.strictEqual( isFunction( arr.toString ), true, 'has method' );
	t.end();
});

tape( 'the method returns an empty string if invoked on an empty array', function test( t ) {
	var str;
	var arr;

	arr = new Float64Array();
	str = arr.toString();

	t.strictEqual( str, '', 'returns expected value' );
	t.end();
});

tape( 'the method returns a string representation of a typed array', function test( t ) {
	var expected;
	var str;
	var arr;

	arr = new Float64Array( [ 1, 2, 3, 4 ] );
	expected = '1,2,3,4';

	str = arr.toString();

	t.strictEqual( str, expected, 'returns expected value' );
	t.end();
});
